// Best-effort HMAC verification. Django signs X-Signature = HMAC-SHA256(
// N8N_SHARED_SECRET, raw compact JSON body). NOTE: n8n's raw-body access varies
// by version, so this is observability-only and does NOT block delivery — enforce
// signatures with n8n native Header Auth or a network control in production.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET || '';
const items = $input.all();
let headers = {};
try { headers = ($input.first().json.headers) || {}; } catch (e) {}
const sig = headers['x-signature'] || headers['X-Signature'] || '';
let raw = '';
try {
  const j = $input.first().json;
  raw = (typeof j.body === 'string') ? j.body : JSON.stringify(j.body != null ? j.body : j);
} catch (e) { raw = ''; }
let valid = false;
try {
  if (secret && sig && raw) {
    const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
    valid = (expected.length === sig.length) &&
            crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
  }
} catch (e) { valid = false; }
return items.map(it => ({ json: Object.assign({}, it.json, { _signature_valid: valid }) }));

// Multilingual newsletter welcome email.
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};
const email = d.email || p.recipient;

const t = {
  en: { subject: 'Welcome to Glitchy ✨', hi: 'Hello,', intro: 'Thanks for subscribing! You will be the first to hear about new drops, restocks and members-only offers.', cta: 'Start shopping', thanks: 'Welcome aboard — Glitchy.' },
  it: { subject: 'Benvenuto in Glitchy ✨', hi: 'Ciao,', intro: 'Grazie per esserti iscritto! Sarai il primo a scoprire nuovi arrivi, riassortimenti e offerte riservate.', cta: 'Inizia lo shopping', thanks: 'Benvenuto a bordo — Glitchy.' },
  fr: { subject: 'Bienvenue chez Glitchy ✨', hi: 'Bonjour,', intro: 'Merci de votre inscription ! Vous serez les premiers informés des nouveautés, réassorts et offres réservées aux membres.', cta: 'Commencer mes achats', thanks: 'Bienvenue à bord — Glitchy.' }
}[lang];
const L = t || { subject: 'Welcome to Glitchy ✨', hi: 'Hello,', intro: 'Thanks for subscribing!', cta: 'Start shopping', thanks: 'Welcome aboard — Glitchy.' };

const shopUrl = $env.SITE_BASE_URL || '';
const btn = shopUrl ? `<p style="margin:18px 0"><a href="${shopUrl}" style="background:#111;color:#fff;padding:10px 18px;text-decoration:none;border-radius:6px;display:inline-block">${L.cta}</a></p>` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${L.subject}</h2>
<p>${L.hi}</p>
<p>${L.intro}</p>
${btn}
<p style="margin-top:20px;color:#666">${L.thanks}</p>
</div>`;

return [{ json: { to: email, subject: L.subject, html } }];
